            message,
        }
    }
    pub fn blank(field: &'static str) -> Self {
        Self::new(StatusCode::UNPROCESSABLE_ENTITY, field, "can't be blank")
    }
    pub fn invalid(field: &'static str) -> Self {
        Self::new(StatusCode::UNPROCESSABLE_ENTITY, field, "is invalid")
    }
    pub fn taken(field: &'static str) -> Self {
        Self::new(StatusCode::CONFLICT, field, "has already been taken")
    }
    pub fn missing(field: &'static str) -> Self {
        Self::new(StatusCode::NOT_FOUND, field, "not found")
    }
    pub fn forbidden(field: &'static str) -> Self {
        Self::new(StatusCode::FORBIDDEN, field, "forbidden")
    }
}

impl From<DbErr> for ApiError {
    fn from(_: DbErr) -> Self {
        Self::new(StatusCode::INTERNAL_SERVER_ERROR, "server", "error")
    }
}

impl From<loco_rs::model::ModelError> for ApiError {
    fn from(_: loco_rs::model::ModelError) -> Self {
        Self::new(StatusCode::INTERNAL_SERVER_ERROR, "server", "error")
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        (
            self.status,
            Json(json!({"errors": {self.field: [self.message]}})),
        )
            .into_response()
    }
}

pub fn json_response<T: Serialize>(status: StatusCode, value: T) -> Response {
    (status, Json(value)).into_response()
}

pub fn required(value: &str, field: &'static str) -> std::result::Result<(), ApiError> {
    if value.trim().is_empty() {
        Err(ApiError::blank(field))
    } else {
        Ok(())
    }
}

pub struct Viewer(pub users::Model);
pub struct OptionalViewer(pub Option<users::Model>);

impl FromRequestParts<AppContext> for OptionalViewer {
    type Rejection = ApiError;

    async fn from_request_parts(
        parts: &mut Parts,
        ctx: &AppContext,
    ) -> std::result::Result<Self, Self::Rejection> {
        let Some(header) = parts.headers.get(axum::http::header::AUTHORIZATION) else {
            return Ok(Self(None));
        };
        let token = header
            .to_str()
            .ok()
            .and_then(|value| value.strip_prefix("Token "))
            .ok_or(ApiError::new(
                StatusCode::UNAUTHORIZED,
                "token",
                "is invalid",
            ))?;
        let config = ctx
            .config
            .get_jwt_config()
            .map_err(|_| ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "server", "error"))?;
        let claims = jwt::JWT::new(&config.secret)
            .validate(token)
            .map_err(|_| ApiError::new(StatusCode::UNAUTHORIZED, "token", "is invalid"))?;
        let user = users::Model::by_pid(&ctx.db, &claims.claims.pid).await?;
        Ok(Self(user))
    }
}

impl FromRequestParts<AppContext> for Viewer {
    type Rejection = ApiError;

    async fn from_request_parts(
        parts: &mut Parts,
        ctx: &AppContext,
    ) -> std::result::Result<Self, Self::Rejection> {
        let OptionalViewer(user) = OptionalViewer::from_request_parts(parts, ctx).await?;
        user.map(Self).ok_or(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "token",
            "is missing",
        ))
    }
}
use axum::{
    extract::{Json, State},
    http::StatusCode,
};
use loco_rs::prelude::*;
use serde::Deserialize;
use serde_json::{json, Value};

use crate::{
    controllers::api::{self, ApiError, ApiResult, Viewer},
    models::users,
    views::realworld::UserView,
};

#[derive(Deserialize)]
struct Envelope<T> {
    user: T,
}

#[derive(Deserialize)]
struct Registration {
    #[serde(default)]
    username: String,
    #[serde(default)]
    email: String,
    #[serde(default)]
    password: String,
}

#[derive(Deserialize)]
struct Login {
    #[serde(default)]
    email: String,
    #[serde(default)]
    password: String,
}

fn response(ctx: &AppContext, user: &users::Model, status: StatusCode) -> ApiResult {
    let config = ctx
        .config
        .get_jwt_config()
        .map_err(|_| ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "server", "error"))?;
    let token = user.token(&config.secret, config.expiration)?;
    Ok(api::json_response(
        status,
        json!({"user": UserView::new(user, token)}),
    ))
}

#[debug_handler]
async fn register(
    State(ctx): State<AppContext>,
    Json(Envelope { user }): Json<Envelope<Registration>>,
) -> ApiResult {
    api::required(&user.username, "username")?;
    api::required(&user.email, "email")?;
    api::required(&user.password, "password")?;
    if users::Model::by_name(&ctx.db, &user.username)
        .await?
        .is_some()
    {
        return Err(ApiError::taken("username"));
    }
    if users::Model::by_email(&ctx.db, &user.email)
        .await?
        .is_some()
    {
        return Err(ApiError::taken("email"));
    }
    let user = users::Model::register(&ctx.db, user.username, user.email, user.password).await?;
    response(&ctx, &user, StatusCode::CREATED)
}

#[debug_handler]
async fn login(
    State(ctx): State<AppContext>,
    Json(Envelope { user }): Json<Envelope<Login>>,
) -> ApiResult {
    api::required(&user.email, "email")?;
    api::required(&user.password, "password")?;
    let user = users::Model::by_email(&ctx.db, &user.email)
        .await?
        .filter(|record| record.verify_password(&user.password))
        .ok_or(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "credentials",
            "invalid",
        ))?;
    response(&ctx, &user, StatusCode::OK)
}

#[debug_handler]
async fn current(Viewer(user): Viewer, State(ctx): State<AppContext>) -> ApiResult {
    response(&ctx, &user, StatusCode::OK)
}

fn text_update(value: &Value, field: &'static str) -> std::result::Result<String, ApiError> {
    let text = value.as_str().ok_or(ApiError::blank(field))?;
    api::required(text, field)?;
    Ok(text.to_owned())
}

#[debug_handler]
async fn update(
    Viewer(user): Viewer,
    State(ctx): State<AppContext>,
    Json(Envelope { user: changes }): Json<Envelope<Value>>,
) -> ApiResult {
    let mut active = user.clone().into_active_model();
    if let Some(value) = changes.get("username") {
        let name = text_update(value, "username")?;
        if name != user.name && users::Model::by_name(&ctx.db, &name).await?.is_some() {
            return Err(ApiError::taken("username"));
        }
        active.name = Set(name);
    }
    if let Some(value) = changes.get("email") {
        let email = text_update(value, "email")?;
        if email != user.email && users::Model::by_email(&ctx.db, &email).await?.is_some() {
            return Err(ApiError::taken("email"));
        }
        active.email = Set(email);
    }
    for (field, slot) in [("bio", &mut active.bio), ("image", &mut active.image)] {
        if let Some(value) = changes.get(field) {
            let text = value.as_str().filter(|s| !s.is_empty()).map(str::to_owned);
            *slot = Set(text);
        }
    }
    if let Some(value) = changes.get("password") {
        let password = text_update(value, "password")?;
        if password.len() < 8 {
            return Err(ApiError::invalid("password"));
        }
        let saved = active.change_password(&ctx.db, &password).await?;
        return response(&ctx, &saved, StatusCode::OK);
    }
    let saved = active.update(&ctx.db).await?;
    response(&ctx, &saved, StatusCode::OK)
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("/api")
        .add("/users", post(register))
        .add("/users/login", post(login))
        .add("/user", get(current))
        .add("/user", put(update))
}
