  if [[ -n "${app_pid:-}" ]]; then kill "$app_pid" 2>/dev/null || true; wait "$app_pid" 2>/dev/null || true; fi
  docker compose -p "$project" down -v >/dev/null 2>&1 || true
  rm "$app_log"
}
trap cleanup EXIT
docker compose -p "$project" down -v >/dev/null 2>&1 || true
docker compose -p "$project" up -d --wait
